def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

print(gcd(48, 180))   # 12
print(lcm(48, 180))   # 720
print(lcm(12, 18))    # 36

